import type { InputProps } from "../../input";
import type { ButtonProps } from "../../button";
import type { IconButtonProps } from "../../icon-button";

// eslint-disable-next-line import/named
import { KEYS, type TLinkElement } from "platejs";
import { forwardRef, useMemo, type ReactNode, type CSSProperties, type Ref } from "react";
import { clsx } from "clsx";
import { InputBox, Link, LinkBroken, NewWindow } from "@exp-textura/icons";
import { useEditorRef, useEditorSelection } from "platejs/react";
import { getLinkAttributes } from "@platejs/link";
import {
  FloatingLinkUrlInput,
  useFloatingLinkEdit,
  useFloatingLinkEditState,
  useFloatingLinkInsert,
  useFloatingLinkInsertState,
} from "@platejs/link/react";
import { flip, offset, type Placement } from "@platejs/floating";

import { Toolbar } from "../../toolbar";
import { Input } from "../../input";
import { Button } from "../../button";
import { LinkButton } from "../../link-button";
import { IconButton } from "../../icon-button";
import { RichTextClasses } from "../rich-text.styles";

// ---------------------------------------------------------------------------
// RichTextLinkInsertToolbar (dumb)
// ---------------------------------------------------------------------------

export interface RichTextLinkInsertToolbarProps extends Omit<ToolbarProps, "variant"> {
  urlInputProps?: InputProps;
  textInputProps?: InputProps;
  onUrlChange?: (url: string) => void;
  onTextChange?: (text: string) => void;
}

export const RichTextLinkInsertToolbar = forwardRef<HTMLDivElement, RichTextLinkInsertToolbarProps>(
  ({ className, urlInputProps, textInputProps, onUrlChange, onTextChange, ...props }, ref) => {
    return (
      <Toolbar
        ref={ref}
        className={clsx(RichTextClasses.linkInsertToolbar, className)}
        style={{ display: "flex", flexDirection: "column", gap: "4px", ...props.style }}
        variant="rte-floating"
        {...(props as ToolbarProps)}
      >
        <Input
          placeholder="Paste link"
          {...urlInputProps}
          onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
            urlInputProps?.onChange?.(e);
            onUrlChange?.(e.target.value);
          }}
        />
        <Input
          placeholder="Text to display"
          {...textInputProps}
          onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
            textInputProps?.onChange?.(e);
            onTextChange?.(e.target.value);
          }}
        />
      </Toolbar>
    );
  },
);

RichTextLinkInsertToolbar.displayName = "RichText.LinkInsertToolbar";

// ---------------------------------------------------------------------------
// RichTextLinkEditToolbar (dumb)
// ---------------------------------------------------------------------------

export interface RichTextLinkEditToolbarProps extends Omit<ToolbarProps, "variant"> {
  href?: string;
  onEdit?: () => void;
  onUnlink?: () => void;
  editButtonProps?: ButtonProps;
  unlinkButtonProps?: IconButtonProps;
  openLinkButtonProps?: React.AnchorHTMLAttributes<HTMLAnchorElement> & { children?: ReactNode };
}

export const RichTextLinkEditToolbar = forwardRef<HTMLDivElement, RichTextLinkEditToolbarProps>(
  (
    {
      className,
      href,
      onEdit,
      onUnlink,
      editButtonProps,
      unlinkButtonProps,
      openLinkButtonProps,
      ...props
    },
    ref,
  ) => {
    return (
      <Toolbar
        ref={ref}
        className={clsx(RichTextClasses.linkEditToolbar, className)}
        style={{ display: "flex", alignItems: "center", gap: "4px", ...props.style }}
        variant="rte-floating"
        {...(props as ToolbarProps)}
      >
        <Toolbar.Item>
          <Button buttonType="tertiary" onClick={onEdit} {...editButtonProps}>
            {editButtonProps?.children ?? "Edit link"}
          </Button>
        </Toolbar.Item>
        <Toolbar.Item>
          <LinkButton
            aria-label="Open link in new tab"
            as="a"
            href={href ?? "#"}
            target="_blank"
            onMouseOver={(e: React.MouseEvent) => e.stopPropagation()}
            {...openLinkButtonProps}
          >
            {openLinkButtonProps?.children ?? <NewWindow />}
          </LinkButton>
        </Toolbar.Item>

        <Toolbar.Item>
          <IconButton
            aria-label="Remove link"
            buttonType="secondary"
            onClick={onUnlink}
            {...unlinkButtonProps}
          >
            {unlinkButtonProps?.children ?? <LinkBroken />}
          </IconButton>
        </Toolbar.Item>
      </Toolbar>
    );
  },
);

RichTextLinkEditToolbar.displayName = "RichText.LinkEditToolbar";

// ---------------------------------------------------------------------------
// FloatingLinkToolbar — composition context
// ---------------------------------------------------------------------------

/**
 * Context provided to the `RichTextFloatingLinkToolbar` render function,
 * exposing all Plate hook outputs needed to build a custom link toolbar UI.
 */
export interface FloatingLinkToolbarContext {
  /** Ref for the insert container — must be attached for floating positioning */
  insertRef: Ref<HTMLDivElement>;
  /** Positioning styles for the insert container */
  insertStyle: CSSProperties;
  /** Props to spread onto the "text to display" input */
  textInputProps: Record<string, unknown>;

  /** Ref for the edit container — must be attached for floating positioning */
  editRef: Ref<HTMLDivElement>;
  /** Positioning styles for the edit container */
  editStyle: CSSProperties;
  /** Props to spread onto the "Edit link" button */
  editButtonProps: Record<string, unknown>;
  /** Props to spread onto the "Remove link" button */
  unlinkButtonProps: Record<string, unknown>;
  /** Whether the edit toolbar is in editing mode (inputs) vs viewing mode (buttons) */
  isEditing: boolean;

  /** Resolved href of the link under the cursor (from Plate's link API) */
  href: string;
  /** Whether the entire toolbar should be hidden (no active link context) */
  hidden: boolean;
}

/**
 * Override default labels for i18n or custom wording.
 * All fields are optional — only override the ones you need.
 */
export interface FloatingLinkToolbarLabels {
  /** Text on the edit button. Default: `"Edit link"` */
  editLink?: string;
  /** aria-label on the open-link button. Default: `"Open link in new tab"` */
  openLink?: string;
  /** aria-label on the unlink button. Default: `"Remove link"` */
  removeLink?: string;
  /** Placeholder for the URL input. Default: `"Paste link"` */
  urlPlaceholder?: string;
  /** Placeholder for the display text input. Default: `"Text to display"` */
  textPlaceholder?: string;
}

export interface RichTextFloatingLinkToolbarProps {
  /** Override default labels for i18n or custom wording. */
  labels?: FloatingLinkToolbarLabels;
  /** Render function for full composition control. When omitted, the default UI renders. */
  children?: (context: FloatingLinkToolbarContext) => ReactNode;
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

// Resolves the href for the link node under the cursor.
// Isolated as its own component so `useEditorSelection` re-renders are scoped here.
function LinkOpenButton({ ariaLabel = "Open link in new tab" }: { ariaLabel?: string }) {
  const editor = useEditorRef();
  const selection = useEditorSelection();

  const attributes = useMemo(() => {
    const entry = editor.api.node<TLinkElement>({
      match: { type: editor.getType(KEYS.link) },
    });
    if (!entry) return {};

    const [element] = entry;
    return getLinkAttributes(editor, element);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editor, selection]);

  return (
    <LinkButton
      aria-label={ariaLabel}
      as="a"
      target="_blank"
      onMouseOver={(e: React.MouseEvent) => e.stopPropagation()}
      {...attributes}
    >
      <NewWindow />
    </LinkButton>
  );
}

/** Resolves the href of the link under the cursor. */
function useLinkHref(): string {
  const editor = useEditorRef();
  const selection = useEditorSelection();

  return useMemo(() => {
    const entry = editor.api.node<TLinkElement>({
      match: { type: editor.getType(KEYS.link) },
    });
    if (!entry) return "";

    const [element] = entry;
    const attrs = getLinkAttributes(editor, element);
    return (attrs.href as string) ?? "";
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editor, selection]);
}

// ---------------------------------------------------------------------------
// RichTextFloatingLinkToolbar (smart, composable)
// ---------------------------------------------------------------------------

// Floating link toolbar — mounts via LinkPlugin's afterEditable render slot.
// Shows an insert popover (Cmd+K) or an edit popover (cursor on existing link).
//
// IMPORTANT: Both toolbars are always rendered — their visibility is controlled
// by the hook-returned props/styles. Conditionally mounting/unmounting causes
// infinite re-render loops because the hooks' internal effects fight with
// React's mount lifecycle.
export function RichTextFloatingLinkToolbar({
  children,
  labels,
}: RichTextFloatingLinkToolbarProps) {
  const resolvedLabels = {
    editLink: labels?.editLink ?? "Edit link",
    openLink: labels?.openLink ?? "Open link in new tab",
    removeLink: labels?.removeLink ?? "Remove link",
    urlPlaceholder: labels?.urlPlaceholder ?? "Paste link",
    textPlaceholder: labels?.textPlaceholder ?? "Text to display",
  };
  const floatingOptions = useMemo(
    () => ({
      middleware: [
        offset(8),
        flip({ fallbackPlacements: ["bottom-end", "top-start", "top-end"], padding: 12 }),
      ],
      placement: "bottom-start" as Placement,
    }),
    [],
  );

  const insertState = useFloatingLinkInsertState({ floatingOptions });
  const {
    hidden,
    props: insertProps,
    ref: insertRef,
    textInputProps,
  } = useFloatingLinkInsert(insertState);

  const editState = useFloatingLinkEditState({ floatingOptions });
  const {
    editButtonProps,
    props: editProps,
    ref: editRef,
    unlinkButtonProps,
  } = useFloatingLinkEdit(editState);

  const href = useLinkHref();

  // -- Composition mode: consumer owns the UI --
  if (typeof children === "function") {
    const context: FloatingLinkToolbarContext = {
      insertRef,
      insertStyle: insertProps.style as CSSProperties,
      textInputProps: textInputProps as Record<string, unknown>,
      editRef,
      editStyle: editProps.style as CSSProperties,
      editButtonProps: editButtonProps as Record<string, unknown>,
      unlinkButtonProps: unlinkButtonProps as Record<string, unknown>,
      isEditing: editState.isEditing,
      href,
      hidden,
    };

    return <>{children(context)}</>;
  }

  // -- Default mode: built-in UI (backward compatible) --
  if (hidden) return null;

  const urlInput = (
    <Toolbar
      style={{ display: "flex", flexDirection: "column", gap: "4px", minWidth: "300px" }}
      variant="rte-floating"
    >
      <FloatingLinkUrlInput as={Input} placeholder={resolvedLabels.urlPlaceholder}>
        <Input.Prefix>
          <Link />
        </Input.Prefix>
      </FloatingLinkUrlInput>
      <Input {...textInputProps} placeholder={resolvedLabels.textPlaceholder}>
        <Input.Prefix>
          <InputBox />
        </Input.Prefix>
      </Input>
    </Toolbar>
  );

  const editContent = editState.isEditing ? (
    urlInput
  ) : (
    <Toolbar variant="rte-floating">
      <Toolbar.Item>
        <Button buttonType="tertiary" {...editButtonProps}>
          {resolvedLabels.editLink}
        </Button>
      </Toolbar.Item>
      <Toolbar.Item>
        <LinkOpenButton ariaLabel={resolvedLabels.openLink} />
      </Toolbar.Item>
      <Toolbar.Item>
        <IconButton
          aria-label={resolvedLabels.removeLink}
          buttonType="secondary"
          {...unlinkButtonProps}
        >
          <LinkBroken />
        </IconButton>
      </Toolbar.Item>
    </Toolbar>
  );

  return (
    <>
      <div ref={insertRef} style={{ ...insertProps.style }}>
        {urlInput}
      </div>
      <div ref={editRef} style={{ ...editProps.style }}>
        {editContent}
      </div>
    </>
  );
}

RichTextFloatingLinkToolbar.displayName = "RichText.FloatingLinkToolbar";
